'use client'

import * as React from 'react'

import './draw-checkbox.css'

export type DrawCheckboxProps = Omit<React.ComponentPropsWithoutRef<'input'>, 'type'> & {
    /** Visible label. */
    label: React.ReactNode
}

// A native checkbox, so form submission, keyboard, labels and screen readers all
// behave exactly like a plain input. Only the box and tick are drawn on top.
const DrawCheckbox = React.forwardRef<HTMLInputElement, DrawCheckboxProps>(({ label, className, style, ...inputProps }, ref) => (
    <label className={['rad-fx-check', className].filter(Boolean).join(' ')} style={style}>
        <span className="rad-fx-check-control">
            <input ref={ref} type="checkbox" className="rad-fx-check-input" {...inputProps} />
            <svg className="rad-fx-check-box" viewBox="0 0 24 24" aria-hidden="true" focusable="false">
                <rect x="2" y="2" width="20" height="20" rx="6" />
                <path d="M6.5 12.5 L10.5 16.5 L17.5 8" pathLength={1} />
            </svg>
        </span>
        <span className="rad-fx-check-label">{label}</span>
    </label>
))

DrawCheckbox.displayName = 'DrawCheckbox'

export default DrawCheckbox

.rad-fx-check {
    display: inline-flex;
    align-items: center;
    gap: 0.6em;
    cursor: pointer;
}

.rad-fx-check-control {
    position: relative;
    display: inline-flex;
    width: 1.35em;
    height: 1.35em;
    flex-shrink: 0;
}

/* The real input covers the drawing, invisible but still focusable and clickable. */
.rad-fx-check-input {
    position: absolute;
    inset: 0;
    margin: 0;
    opacity: 0;
    cursor: pointer;
}

.rad-fx-check-box {
    width: 100%;
    height: 100%;
    overflow: visible;
}

.rad-fx-check-box rect {
    fill: transparent;
    stroke: currentcolor;
    stroke-width: 1.8;
    transition: fill 200ms ease, stroke 200ms ease;
}

.rad-fx-check-box path {
    fill: none;
    stroke: var(--rad-fx-check-tick, #0b0b0f);
    stroke-width: 2.6;
    stroke-linecap: round;
    stroke-linejoin: round;
    stroke-dasharray: 1;
    stroke-dashoffset: 1;
    transition: stroke-dashoffset 280ms cubic-bezier(0.6, 0.1, 0.3, 1) 60ms;
}

.rad-fx-check-input:checked + .rad-fx-check-box rect {
    fill: var(--rad-fx-check-color, #a78bfa);
    stroke: var(--rad-fx-check-color, #a78bfa);
}

.rad-fx-check-input:checked + .rad-fx-check-box path { stroke-dashoffset: 0; }

.rad-fx-check-input:focus-visible + .rad-fx-check-box {
    outline: 2px solid currentcolor;
    outline-offset: 2px;
    border-radius: 7px;
}

.rad-fx-check-input:disabled + .rad-fx-check-box { opacity: 0.5; }

@media (prefers-reduced-motion: reduce) {
    .rad-fx-check-box rect, .rad-fx-check-box path { transition: none; }
}

[data-rad-fx-motion='reduce'] .rad-fx-check-box rect,
[data-rad-fx-motion='reduce'] .rad-fx-check-box path { transition: none; }
